package com.enterprise.siem.alert;
import com.enterprise.siem.database.AlertRepository; import com.enterprise.siem.incident.IncidentManager; import com.enterprise.siem.model.Alert; import com.enterprise.siem.util.SIEMMetrics; import org.slf4j.*; import java.sql.SQLException; import java.time.Duration; import java.time.Instant; import java.util.Iterator; import java.util.LinkedHashMap; import java.util.Map;
 public final class AlertManager { private static final Logger log=LoggerFactory.getLogger(AlertManager.class); private static final int MAX_DEDUP_KEYS=100_000; private static final Duration DEDUP_TTL=Duration.ofMinutes(15); private final AlertRepository repository; private final IncidentManager incidents; private final SIEMMetrics metrics; private final Map<String,Alert> seen=new LinkedHashMap<>(128,0.75f,true);
 public AlertManager(AlertRepository r,IncidentManager i,SIEMMetrics m){repository=r;incidents=i;metrics=m;}
 public synchronized void accept(Alert a){Instant now=Instant.now();cleanup(now);String key=a.ruleId()+":"+a.sourceIp()+":"+a.hostname();Alert aggregate=seen.get(key);if(aggregate!=null){Alert updated=aggregate.occurrence(a.timestamp());seen.put(key,updated);try{repository.save(updated);}catch(SQLException e){metrics.databaseErrors.increment();log.error("Unable to update alert {}",a.alertId(),e);}return;}seen.put(key,a);if(seen.size()>MAX_DEDUP_KEYS){seen.entrySet().iterator().remove();metrics.evictedKeys.increment();}try{if(repository.save(a)){metrics.alertsGenerated.increment();log.warn("Alert {} {}",a.ruleId(),a.description());if(a.severity()==com.enterprise.siem.model.Severity.HIGH||a.severity()==com.enterprise.siem.model.Severity.CRITICAL)incidents.accept(a);}}catch(SQLException e){metrics.databaseErrors.increment();log.error("Unable to persist alert {}",a.alertId(),e);}}
 private void cleanup(Instant now){Iterator<Map.Entry<String,Alert>> iterator=seen.entrySet().iterator();while(iterator.hasNext())if(Duration.between(iterator.next().getValue().lastSeen(),now).compareTo(DEDUP_TTL)>0){iterator.remove();metrics.evictedKeys.increment();}}
}
